using System.Diagnostics;
using System.Globalization;
using Avalonia;
using Avalonia.Controls;
using MindBuzz.Core.Editing;
using MindBuzz.Core.Layout;
using MindBuzz.Core.Model;

namespace MindBuzz.App.Canvas;

/// <summary>
/// The canvas's performance measurement: runs inside the real app on real hardware, against a map
/// generated by <c>tests/SyntheticMap</c>, and prints the numbers. Start it with
/// <c>MindBuzz &lt;file.mbz&gt; --bench</c>. Diagnostics, so the output is invariant and not in Strings.resx.
/// <para>
/// Frame times come from the canvas's own <c>Render</c> (UI thread) and the interval between rendered frames.
/// Avalonia rasterises on a separate render thread; if that fell behind, frames would arrive less often, which the
/// interval shows.
/// </para>
/// </summary>
internal static class CanvasBenchmark
{
    private const int FramesPerPhase = 240;

    public static void Run(MapCanvas canvas, Action<string> report, Action done)
    {
        ArgumentNullException.ThrowIfNull(canvas);
        TopLevel top = TopLevel.GetTopLevel(canvas)!;
        var phases = new Queue<Phase>();
        var results = new List<string>();

        Map map = canvas.Map!;
        results.Add(Invariant($"map              {map.Index.Count} topics, {canvas.CurrentLayout?.Boxes.Count} visible, window {canvas.Bounds.Width:0}x{canvas.Bounds.Height:0}"));
        results.AddRange(MeasureLayout(canvas, map));

        Viewport fitted = Viewport.Fit(canvas.CurrentLayout!.Bounds, canvas.Bounds.Size);
        var size = canvas.Bounds.Size;

        // Pan across the whole map while fitted, then at 100 % around the centre, then zoom in and out.
        phases.Enqueue(new Phase("pan, fitted", frame => fitted.PanBy(new Vector(Math.Sin(frame / 20.0) * 200, Math.Cos(frame / 25.0) * 120))));
        phases.Enqueue(new Phase("pan, 100 %", frame =>
            new Viewport(1, new Point(size.Width / 2, size.Height / 2)).PanBy(new Vector(Math.Sin(frame / 30.0) * 1500, Math.Cos(frame / 35.0) * 1500))));
        phases.Enqueue(new Phase("zoom 25–150 %", frame =>
            fitted.ZoomAround(new Point(size.Width / 2, size.Height / 2), 0.25 + (1.25 * (0.5 - (0.5 * Math.Cos(frame / 30.0)))))));

        // A short idle warm-up first, so JIT and first-time shaping are not in the numbers.
        int warmup = 30;
        Phase? current = null;
        int frame = 0;

        void Tick(TimeSpan _)
        {
            if (warmup-- > 0)
            {
                canvas.InvalidateVisual();
                top.RequestAnimationFrame(Tick);
                return;
            }

            if (current is null || frame >= FramesPerPhase)
            {
                if (current is not null)
                {
                    results.Add(Summary(current.Name, canvas));
                }

                if (!phases.TryDequeue(out current))
                {
                    GC.Collect();
                    GC.WaitForPendingFinalizers();
                    results.Add(Invariant($"working set      {Environment.WorkingSet / (1024.0 * 1024):0} MiB, managed heap {GC.GetTotalMemory(forceFullCollection: true) / (1024.0 * 1024):0} MiB"));
                    foreach (string line in results)
                    {
                        report(line);
                    }

                    done();
                    return;
                }

                frame = 0;
                canvas.Stats.Reset();
                Console.Error.WriteLine(Invariant($"[bench] {DateTime.Now:HH:mm:ss.f} phase {current.Name}"));
            }

            canvas.SetViewport(current.At(frame++), animate: false);
            top.RequestAnimationFrame(Tick);
        }

        top.RequestAnimationFrame(Tick);
    }

    /// <summary>A full layout with a cold and a warm text cache, then incremental layouts after single text
    /// edits.</summary>
    private static IEnumerable<string> MeasureLayout(MapCanvas canvas, Map map)
    {
        var coldText = new TopicText();
        var clock = Stopwatch.StartNew();
        new LayoutEngine(coldText).Layout(map);
        double cold = clock.Elapsed.TotalMilliseconds;

        var warm = new List<double>();
        for (int i = 0; i < 5; i++)
        {
            clock.Restart();
            new LayoutEngine(coldText).Layout(map);
            warm.Add(clock.Elapsed.TotalMilliseconds);
        }

        coldText.Release();

        // Incremental: what the canvas does after an edit. Its engine keeps the shapes of unchanged subtrees.
        var random = new Random(1);
        Topic[] topics = [.. map.Root.DescendantsAndSelf()];
        var document = new Document([map]);
        var incremental = new List<double>();
        for (int i = 0; i < 20; i++)
        {
            Topic target = topics[random.Next(topics.Length)];
            document = new SetTopicText(map.Id, target.Id, $"{target.Text} edited {i}").Apply(document).After ?? document;
            canvas.Map = document.Maps[0];
            incremental.Add(canvas.LastLayoutMs);
        }

        canvas.Map = map;

        yield return Invariant($"layout, full     {cold:0.0} ms cold text cache, {Median(warm):0.0} ms warm (median of 5)");
        yield return Invariant($"layout, edit     {Median(incremental):0.00} ms median, {incremental.Max():0.00} ms max (20 single-topic text edits)");
    }

    private static string Summary(string name, MapCanvas canvas)
    {
        FrameStats stats = canvas.Stats;
        return Invariant(
            $"{name,-16} {stats.Fps,5:0} fps  interval p50 {stats.IntervalP50:0.0} ms  p95 {stats.IntervalP95:0.0} ms  render p50 {stats.RenderP50:0.00} ms  p95 {stats.RenderP95:0.00} ms  max {stats.RenderMax:0.00} ms");
    }

    private static double Median(List<double> values)
    {
        values.Sort();
        return values[values.Count / 2];
    }

    private static string Invariant(FormattableString text) => text.ToString(CultureInfo.InvariantCulture);

    private sealed record Phase(string Name, Func<int, Viewport> At);
}
